edits.before:
const exclusive = input.getAttribute('data-checkbox-exclusive');
if (exclusive) {
  const group = input.getAttribute('data-checkbox-exclusive-group');
  if (group) {
    root.querySelectorAll(`[data-checkbox-exclusive-group="${group}"]`).forEach(other => {
      if (other !== input) other.checked = false;
    });
  } else {
    root.querySelectorAll('[data-checkbox-exclusive]').forEach(other => {
      if (other !== input) other.checked = false;
    });
  }
}

